import{_ as e,o as a,c as i,ag as r}from"./chunks/framework.DTisvaUJ.js";const c=JSON.parse('{"title":"支援版(ライセンス)","description":"Mutelinkの本体は無料です。BOOTHで購入できる任意の拡張機能とライセンスの種類、追加できる機能、読み込み方を案内します。","frontmatter":{"description":"Mutelinkの本体は無料です。BOOTHで購入できる任意の拡張機能とライセンスの種類、追加できる機能、読み込み方を案内します。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/about/supporter"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"支援版(ライセンス) | Mutelink"}],["meta",{"property":"og:description","content":"Mutelinkの本体は無料です。BOOTHで購入できる任意の拡張機能とライセンスの種類、追加できる機能、読み込み方を案内します。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/about/supporter"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"支援版(ライセンス) | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelinkの本体は無料です。BOOTHで購入できる任意の拡張機能とライセンスの種類、追加できる機能、読み込み方を案内します。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/about/supporter"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/about/supporter"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/supporter"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/supporter"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/about/supporter"}]]},"headers":[],"relativePath":"about/supporter.md","filePath":"about/supporter.md"}'),n={name:"about/supporter.md"};function l(o,t,u,p,s,h){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="支援版-ライセンス" tabindex="-1">支援版(ライセンス) <a class="header-anchor" href="#支援版-ライセンス" aria-label="Permalink to &quot;支援版(ライセンス)&quot;">​</a></h1><p>アプリ本体は無料です。支援版は、機能をさらに広げる有料の拡張で、買わなくても、アプリ本体は使えます。</p><h2 id="種類" tabindex="-1">種類 <a class="header-anchor" href="#種類" aria-label="Permalink to &quot;種類&quot;">​</a></h2><p><a href="https://utyujin.booth.pm/items/8914909" target="_blank" rel="noreferrer">BOOTHの商品ページ</a>で販売しています。</p><table tabindex="0"><thead><tr><th>名前</th><th>価格</th><th>できること</th></tr></thead><tbody><tr><td>カスタマイズ拡張</td><td>500円</td><td>VRキーボードなどの背景画像を、自由に設定できます。チャットボックスに出す文章のレイアウトを、自由に編集できます。VRの中のパネルやコントロールパネルを、手に付けられます。メイン画面の背景を透かして、VRChatに重ねて置けます</td></tr><tr><td>AI音声拡張</td><td>1,000円</td><td>声の登録(声のクローン。Irodori-TTSとQwen3-TTS)、語尾ごとの絵文字・スタイル・声の設定ができます。翻訳した文の読み上げ(VOICEVOXで読むときも)も、できるようになります</td></tr><tr><td>2つセット</td><td>1,200円</td><td>上の2つの両方が使えます</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">名前が変わりました</p><p>v2.0.0から、「VR背景・チャットボックス拡張」は「カスタマイズ拡張」に、「IrodoriTTS拡張」は「AI音声拡張」に、名前を変えました。中身が増えたためで、購入済みのライセンスのファイルは、そのまま使えます。</p></div><h2 id="無料で使えるもの" tabindex="-1">無料で使えるもの <a class="header-anchor" href="#無料で使えるもの" aria-label="Permalink to &quot;無料で使えるもの&quot;">​</a></h2><p>次のものは、買わなくても使えます。</p><ul><li>音声認識、キーボードとVRキーボードでの入力、チャットボックスへの送信</li><li>VOICEVOX、Irodori-TTS(標準の声)、Qwen3-TTS(標準の声)での読み上げ</li><li>翻訳と、訳した文のチャットボックスへの送信</li><li>聞こえた声(認識、翻訳、表示)</li><li>VRの中のパネルを、視界に出すこと</li><li>地声をそのまま出すこと</li></ul><div class="tip custom-block"><p class="custom-block-title">買う前に</p><p>Irodori-TTSとQwen3-TTSは、インストールと、標準の声での読み上げまでが無料です。お使いのPCで動くことを、無料の範囲で確認してから、購入してください。<a href="/Mutelink-releases/compare/voices">読み上げの声の聞き比べ</a>で、声を聞けます。</p><p>Qwen3-TTSの声のクローンを会話に使う場合は、クローン用モデルに加え、NVIDIAのGPUと高速化部品も用意してください。高速化部品なしでは生成が再生に追いつかない測定結果があるため、先に標準の声で速さを確認します。</p></div><h2 id="使いかた" tabindex="-1">使いかた <a class="header-anchor" href="#使いかた" aria-label="Permalink to &quot;使いかた&quot;">​</a></h2><ol><li>BOOTHで購入すると、ライセンスのファイルをダウンロードできます。</li><li>Mutelinkの 設定 &gt; そのほか &gt; ライセンス で、そのファイルを読み込みます。</li><li>読み込めると、その拡張の機能にかかっていた鍵が外れて、操作できるようになります。</li></ol><p>どのライセンスが有効かは、同じページで確認できます。</p><h2 id="利用上の決まり" tabindex="-1">利用上の決まり <a class="header-anchor" href="#利用上の決まり" aria-label="Permalink to &quot;利用上の決まり&quot;">​</a></h2><ul><li>ライセンスのファイルは、購入した本人が、ご自身のPCで使う目的に限って使えます</li><li>再配布、販売、第三者への譲渡や共有は、禁止です</li><li>ファイルの改変や、有料機能を不正に有効にすることは、禁止です</li><li>声の登録は、ご自身の声、または、声の持ち主から明確な同意を得た声に限ります。声優、有名人、知人などの声を、本人の同意なく登録することや、他人へのなりすまし、人を欺く目的の合成音声(ディープフェイクなど)に使うことは、禁止です</li><li>この機能は、音声に透かし(ウォーターマーク)を付けません。生成した音声の使いかたは、すべて利用者の責任です</li><li>法令や、VRChatのルールに反する使いかたは、禁止です</li></ul><p>返金、サポート、更新、免責については、BOOTHの商品ページをご覧ください。</p>',16)])])}const m=e(n,[["render",l]]);export{c as __pageData,m as default};
